import os
import json
import uuid
import threading
from datetime import datetime, timezone
import httpx
from flask import Flask, request, Response, send_from_directory
from cerebras.cloud.sdk import Cerebras

app = Flask(__name__, static_folder="static")

cerebras_client = Cerebras(api_key=os.environ.get("CEREBRAS_API_KEY"))

EXA_API_KEY = os.environ.get("EXA_API_KEY", "")
EXA_SEARCH_URL = ""
EXA_NUM_RESULTS = 100

sessions_lock = threading.Lock()
sessions: dict[str, list[dict]] = {}

MODEL = "zai-glm-4.7"
MAX_TOKENS = 65000
TEMPERATURE = 0
TOP_P = 0.95

def build_system_prompt() -> str:
    now = datetime.now(timezone.utc)
    date_str = now.strftime("%Y-%m-%d")
    time_str = now.strftime("%H:%M UTC")
    return f"""You are a highly capable AI assistant with access to a real-time web search tool called `exa_search`.

## Current date and time
Today is {date_str}. Current time: {time_str}.
Always use this date as your reference when evaluating how recent information is, deciding whether to search for updates, or answering questions about current events.

## When to search
Use `exa_search` whenever the user's question would benefit from current, factual, or detailed information from the web — including news, research, documentation, people, companies, events, or any topic where up-to-date knowledge matters.

## Search mode selection
You must choose the `type` parameter based on query complexity:
- `instant` — extremely simple, factual lookups (e.g. "what is the capital of France")
- `fast` — straightforward questions needing quick web results
- `deep` — complex, multi-faceted research questions requiring thorough investigation

## Multiple searches
You may call `exa_search` as many times as needed within a single response. If the first search reveals you need more specific information, search again with a refined query. Keep searching until you have enough information to give a complete, accurate answer.

## Using search results
You will receive ONLY the AI-generated summaries from each search result. Use these summaries as your primary knowledge source to construct your answer. Do not make up facts — base your answer strictly on what the summaries tell you. If the summaries are insufficient, search again.

## Response format
After gathering all needed information through searches, write a comprehensive, well-structured response in the same language as the user's question. Cite sources naturally when relevant."""

EXA_SEARCH_TOOL = {
    "type": "function",
    "function": {
        "name": "exa_search",
        "description": (
            "Search the web using Exa AI. Always returns 100 results with AI-generated summaries. "
            "Choose type based on complexity: 'instant' for trivial facts, 'fast' for standard queries, "
            "'deep' for complex multi-step research. You can call this multiple times per response."
        ),
        "parameters": {
            "type": "object",
            "properties": {
                "query": {
                    "type": "string",
                    "description": "The search query. Be specific and descriptive for best results."
                },
                "type": {
                    "type": "string",
                    "enum": ["instant", "fast", "deep"],
                    "description": "Search mode: 'instant' for simple lookups, 'fast' for standard searches, 'deep' for complex research."
                },
                "category": {
                    "type": "string",
                    "enum": ["company", "people", "research paper", "news", "personal site", "financial report"],
                    "description": "Optional: restrict results to a specific content category."
                },
                "startPublishedDate": {
                    "type": "string",
                    "description": "Optional ISO 8601 date string (e.g. '2024-01-01'). Only return results published after this date."
                },
                "endPublishedDate": {
                    "type": "string",
                    "description": "Optional ISO 8601 date string. Only return results published before this date."
                },
                "includeDomains": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "Optional: restrict results to these domains only."
                },
                "excludeDomains": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "Optional: exclude results from these domains."
                }
            },
            "required": ["query", "type"]
        }
    }
}


def exa_search(
    query: str,
    search_type: str,
    category: str | None = None,
    start_published_date: str | None = None,
    end_published_date: str | None = None,
    include_domains: list[str] | None = None,
    exclude_domains: list[str] | None = None,
) -> dict:
    headers = {
        "x-api-key": EXA_API_KEY,
        "Content-Type": "application/json",
        "Accept": "application/json",
    }

    payload: dict = {
        "query": query,
        "type": search_type,
        "numResults": EXA_NUM_RESULTS,
        "contents": {
            "summary": True,
        },
    }

    if category:
        payload["category"] = category
    if start_published_date:
        payload["startPublishedDate"] = start_published_date
    if end_published_date:
        payload["endPublishedDate"] = end_published_date
    if include_domains:
        payload["includeDomains"] = include_domains
    if exclude_domains and category not in ("company", "people"):
        payload["excludeDomains"] = exclude_domains

    try:
        with httpx.Client(timeout=120.0) as client:
            resp = client.post(EXA_SEARCH_URL, headers=headers, json=payload)
            resp.raise_for_status()
            data = resp.json()
    except httpx.HTTPStatusError as exc:
        return {"error": f"Exa API HTTP error {exc.response.status_code}: {exc.response.text[:400]}"}
    except Exception as exc:
        return {"error": f"Exa API request failed: {str(exc)}"}

    results = data.get("results", [])
    search_type_used = data.get("searchType", search_type)

    formatted: list[dict] = []
    for r in results:
        summary = (r.get("summary") or "").strip()
        if not summary:
            continue
        entry: dict = {
            "url": r.get("url", ""),
            "title": (r.get("title") or "").strip(),
            "summary": summary,
        }
        if r.get("publishedDate"):
            entry["publishedDate"] = r["publishedDate"][:10]
        formatted.append(entry)

    return {
        "query": query,
        "searchType": search_type_used,
        "totalResults": len(formatted),
        "results": formatted,
    }


def call_exa_tool(tool_args: dict) -> tuple[str, list[dict]]:
    result = exa_search(
        query=tool_args.get("query", ""),
        search_type=tool_args.get("type", "fast"),
        category=tool_args.get("category") or None,
        start_published_date=tool_args.get("startPublishedDate") or None,
        end_published_date=tool_args.get("endPublishedDate") or None,
        include_domains=tool_args.get("includeDomains") or None,
        exclude_domains=tool_args.get("excludeDomains") or None,
    )

    sources: list[dict] = [
        {"url": r["url"], "title": r["title"]}
        for r in result.get("results", [])[:20]
        if r.get("url")
    ]

    model_results: list[dict] = []
    for r in result.get("results", []):
        entry: dict = {"summary": r["summary"]}
        if r.get("publishedDate"):
            entry["publishedDate"] = r["publishedDate"]
        model_results.append(entry)

    model_payload: dict = {
        "query": result["query"],
        "searchType": result["searchType"],
        "totalResults": result["totalResults"],
        "results": model_results,
    }

    return json.dumps(model_payload, ensure_ascii=False), sources


def get_session(session_id: str) -> list[dict]:
    with sessions_lock:
        return list(sessions.get(session_id, []))


def set_session(session_id: str, messages: list[dict]) -> None:
    with sessions_lock:
        sessions[session_id] = messages


def delete_session(session_id: str) -> None:
    with sessions_lock:
        sessions.pop(session_id, None)


def build_cerebras_messages(history: list[dict], new_message: str) -> list[dict]:
    cerebras_messages: list[dict] = [{"role": "system", "content": build_system_prompt()}]

    for msg in history:
        role = msg.get("role", "user")
        content = msg.get("content", "")
        cerebras_messages.append({"role": role, "content": content})

    cerebras_messages.append({"role": "user", "content": new_message})
    return cerebras_messages


def sse_event(event_type: str, data: dict) -> str:
    payload = json.dumps({"type": event_type, "data": data}, ensure_ascii=False)
    return f"data: {payload}\n\n"


def agentic_stream(initial_messages: list[dict]):
    current_messages = list(initial_messages)
    full_assistant_response = ""
    search_count = 0

    while True:
        tool_calls_accumulated: dict[int, dict] = {}
        delta_text_this_turn = ""
        finish_reason = None
        had_error = False

        try:
            stream = cerebras_client.chat.completions.create(
                messages=current_messages,
                model=MODEL,
                stream=True,
                max_completion_tokens=MAX_TOKENS,
                temperature=TEMPERATURE,
                top_p=TOP_P,
                tools=[EXA_SEARCH_TOOL],
                tool_choice="auto",
            )

            for chunk in stream:
                choice = chunk.choices[0]
                if choice.finish_reason:
                    finish_reason = choice.finish_reason

                if choice.delta.content:
                    token = choice.delta.content
                    delta_text_this_turn += token
                    full_assistant_response += token
                    yield sse_event("content", {"delta": token})

                if choice.delta.tool_calls:
                    for tc in choice.delta.tool_calls:
                        idx = tc.index
                        if idx not in tool_calls_accumulated:
                            tool_calls_accumulated[idx] = {
                                "id": "",
                                "type": "function",
                                "function": {"name": "", "arguments": ""},
                            }
                        if tc.id:
                            tool_calls_accumulated[idx]["id"] = tc.id
                        if tc.function:
                            if tc.function.name:
                                tool_calls_accumulated[idx]["function"]["name"] += tc.function.name
                            if tc.function.arguments:
                                tool_calls_accumulated[idx]["function"]["arguments"] += tc.function.arguments

        except Exception as exc:
            yield sse_event("error", {"message": f"Model error: {str(exc)}"})
            had_error = True
            break

        if had_error:
            break

        if not tool_calls_accumulated:
            break

        tool_calls_list = [tool_calls_accumulated[k] for k in sorted(tool_calls_accumulated.keys())]

        current_messages.append({
            "role": "assistant",
            "content": delta_text_this_turn if delta_text_this_turn else None,
            "tool_calls": tool_calls_list,
        })

        for tc in tool_calls_list:
            tool_name = tc["function"]["name"]
            raw_args = tc["function"]["arguments"]
            tool_call_id = tc["id"]

            try:
                tool_args = json.loads(raw_args) if raw_args else {}
            except json.JSONDecodeError:
                tool_args = {}

            search_count += 1
            search_query = tool_args.get("query", "")
            search_mode = tool_args.get("type", "fast")

            yield sse_event("search_start", {
                "query": search_query,
                "mode": search_mode,
                "searchIndex": search_count,
            })

            if tool_name == "exa_search":
                tool_result_str, sources = call_exa_tool(tool_args)
                try:
                    result_count = json.loads(tool_result_str).get("totalResults", 0)
                except Exception:
                    result_count = 0
            else:
                tool_result_str = json.dumps({"error": f"Unknown tool: {tool_name}"})
                sources = []
                result_count = 0

            yield sse_event("search_done", {
                "query": search_query,
                "count": result_count,
                "searchIndex": search_count,
                "sources": sources,
            })

            current_messages.append({
                "role": "tool",
                "tool_call_id": tool_call_id,
                "content": tool_result_str,
            })

        if finish_reason == "stop":
            break

    yield {"__final__": True, "full_response": full_assistant_response}


@app.route("/")
def index():
    return send_from_directory(".", "index.html")


@app.route("/static/<path:filename>")
def static_files(filename):
    return send_from_directory("static", filename)


@app.route("/sw.js")
def service_worker():
    sw_path = os.path.join("static", "sw.js")
    if os.path.exists(sw_path):
        return send_from_directory("static", "sw.js", mimetype="application/javascript")
    js = (
        "self.addEventListener('install', function(e) { self.skipWaiting(); });"
        "self.addEventListener('activate', function(e) { e.waitUntil(self.clients.claim()); });"
    )
    return Response(js, mimetype="application/javascript", headers={"Cache-Control": "no-cache"})


@app.route("/static/manifest.json")
def manifest():
    manifest_path = os.path.join("static", "manifest.json")
    if os.path.exists(manifest_path):
        return send_from_directory("static", "manifest.json")
    data = {
        "name": "Chat",
        "short_name": "Chat",
        "start_url": "/",
        "display": "standalone",
        "background_color": "#020403",
        "theme_color": "#020403",
        "icons": [
            {"src": "/static/icon-192.png", "sizes": "192x192", "type": "image/png"},
            {"src": "/static/icon-180.png", "sizes": "180x180", "type": "image/png"},
        ],
    }
    return Response(json.dumps(data), mimetype="application/json")


@app.route("/api/chat", methods=["POST"])
def chat():
    body = request.get_json(force=True, silent=True) or {}
    message = body.get("message", "").strip()
    session_id = body.get("session_id", "").strip()

    if not message:
        return Response(
            sse_event("error", {"message": "Üres üzenet"}),
            mimetype="text/event-stream",
            status=400,
        )

    if not session_id:
        session_id = str(uuid.uuid4())

    history = get_session(session_id)
    cerebras_messages = build_cerebras_messages(history, message)

    def generate():
        full_response = ""
        try:
            yield sse_event("session", {"sid": session_id})

            for item in agentic_stream(cerebras_messages):
                if isinstance(item, dict) and item.get("__final__"):
                    full_response = item.get("full_response", "")
                elif isinstance(item, str):
                    yield item

        except Exception as exc:
            yield sse_event("error", {"message": str(exc)})

        new_history = list(history)
        new_history.append({"role": "user", "content": message})
        if full_response:
            new_history.append({"role": "assistant", "content": full_response})
        set_session(session_id, new_history)

        yield sse_event("done", {})

    return Response(
        generate(),
        mimetype="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
            "Connection": "keep-alive",
        },
    )


@app.route("/api/new", methods=["POST"])
def new_chat():
    old_sid = (request.get_json(force=True, silent=True) or {}).get("session_id", "").strip()
    if old_sid:
        delete_session(old_sid)
    new_sid = str(uuid.uuid4())
    return Response(json.dumps({"session_id": new_sid}), mimetype="application/json")


@app.route("/api/history", methods=["GET", "DELETE"])
def history():
    session_id = request.args.get("session_id", "").strip()
    if not session_id:
        return Response(
            json.dumps({"error": "Hiányzó session_id"}),
            mimetype="application/json",
            status=400,
        )

    if request.method == "DELETE":
        delete_session(session_id)
        return Response(json.dumps({"ok": True}), mimetype="application/json")

    msgs = get_session(session_id)
    result = []
    for m in msgs:
        result.append({
            "role": m.get("role", "user"),
            "content": m.get("content", ""),
        })

    return Response(json.dumps(result, ensure_ascii=False), mimetype="application/json")


if __name__ == "__main__":
    port = int(os.environ.get("PORT", 5000))
    app.run(host="0.0.0.0", port=port, debug=False, threaded=True)
